/* A CrlEntry is a bare HashedId8 and never says which hash produced it, so both of the
 * caller's forms are looked up here. Without a list there is no table and nothing matches.
 * The slot is returned, not just a yes, because its_crl_list_of needs it. */
static int revoked_slot(const uint8_t id8[8])
{
#if ITS_CRL_COUNT > 0
    size_t lo = 0;
    size_t hi = ITS_CRL_COUNT;
    while (lo < hi)
    {
        size_t mid = lo + (hi - lo) / 2;
        int c = memcmp(id8, s_revoked[mid], 8);
        if (c == 0)
            return (int)mid;
        if (c < 0)
            hi = mid;
        else
            lo = mid + 1;
    }
#else
    (void)id8;
#endif
    return -1;
}

/* The slot of whichever of the caller's two forms a list names, or -1 for neither. */
static int revoked_either(const uint8_t id8_sha256[8], const uint8_t id8_sha384[8])
{
    int i = id8_sha256 ? revoked_slot(id8_sha256) : -1;
    if (i < 0 && id8_sha384)
        i = revoked_slot(id8_sha384);
    return i;
}

its_crl_state_t its_crl_lookup(const uint8_t id8_sha256[8], const uint8_t id8_sha384[8])
{
    /* Without a list nothing can be said, and nothing can be said either when the caller
     * hands over no identifier at all. Only a list that names nobody means not listed. */
    if (ITS_CRL_LIST_COUNT == 0 || (!id8_sha256 && !id8_sha384))
        return ITS_CRL_NO_DATA;
    if (revoked_either(id8_sha256, id8_sha384) >= 0)
        return ITS_CRL_LISTED;
    return ITS_CRL_NOT_LISTED;
}

/* Copy one list, so the user interface can name what the firmware really holds. */
/* Walk the withdrawn identifiers themselves, so a page can show them instead of only their
 * number. list_index says which list named the entry; where two lists name the same one it
 * is the older of them, the same choice its_crl_list_of makes. */
bool its_crl_revoked_at(size_t index, uint8_t out_id8[8], size_t *list_index)
{
#if ITS_CRL_COUNT > 0
    if (index < ITS_CRL_COUNT)
    {
        if (out_id8)
            memcpy(out_id8, s_revoked[index], 8);
        if (list_index)
            *list_index = s_revoked_list[index];
        return true;
    }
#else
    (void)index;
    (void)out_id8;
    (void)list_index;
#endif
    return false;
}

bool its_crl_list_at(size_t index, its_crl_list_t *out)
{
#if ITS_CRL_LIST_COUNT > 0
    if (index < ITS_CRL_LIST_COUNT)
    {
        if (out)
            *out = s_lists[index];
        return true;
    }
#else
    (void)index;
    (void)out;
#endif
    return false;
}

/* The entries are sorted across all lists, so s_revoked_list carries the list each one came
 * from. Without it a verdict could only be shown beside the oldest date of the whole set. */
bool its_crl_list_of(const uint8_t id8_sha256[8], const uint8_t id8_sha384[8], size_t *index)
{
#if ITS_CRL_COUNT > 0
    int i = revoked_either(id8_sha256, id8_sha384);
    if (i >= 0)
    {
        if (index)
            *index = s_revoked_list[i];
        return true;
    }
#else
    (void)id8_sha256;
    (void)id8_sha384;
    (void)index;
#endif
    return false;
}

size_t its_crl_count(void)
{
    return ITS_CRL_COUNT;
}

size_t its_crl_lists(void)
{
    return ITS_CRL_LIST_COUNT;
}

/* Both dates are taken from the list table itself, so they cannot drift away from it. */
uint32_t its_crl_oldest_update(void)
{
    uint32_t t = 0;
#if ITS_CRL_LIST_COUNT > 0
    t = s_lists[0].this_update;
    for (size_t i = 1; i < ITS_CRL_LIST_COUNT; i++)
        if (s_lists[i].this_update < t)
            t = s_lists[i].this_update;
#endif
    return t;
}

/* The other end of the span. With it the page can say how far the set reaches instead of
 * letting its oldest list speak for all of them. */
uint32_t its_crl_newest_update(void)
{
    uint32_t t = 0;
#if ITS_CRL_LIST_COUNT > 0
    t = s_lists[0].this_update;
    for (size_t i = 1; i < ITS_CRL_LIST_COUNT; i++)
        if (s_lists[i].this_update > t)
            t = s_lists[i].this_update;
#endif
    return t;
}

uint32_t its_crl_next_update(void)
{
    uint32_t t = 0;
#if ITS_CRL_LIST_COUNT > 0
    t = s_lists[0].next_update;
    for (size_t i = 1; i < ITS_CRL_LIST_COUNT; i++)
        if (s_lists[i].next_update < t)
            t = s_lists[i].next_update;
#endif
    return t;
}

/* How many lists asked to be renewed before `now`. One abandoned list would otherwise make
 * the earliest date above speak for all of them. */
size_t its_crl_overdue(uint32_t now)
{
    size_t n = 0;
#if ITS_CRL_LIST_COUNT > 0
    if (!now)
        return 0;
    /* Same rule as the table on /trust: a list that never asked for a renewal
     * cannot be late. Counting it here would make the two disagree. */
    for (size_t i = 0; i < ITS_CRL_LIST_COUNT; i++)
        if (s_lists[i].next_update && s_lists[i].next_update <= now)
            n++;
#else
    (void)now;
#endif
    return n;
}
